function validate([columnTitle]) {
  if (columnTitle.length < 1 || columnTitle.length > 7) return 'columnTitle has 1 to 7 letters.';
  if (!/^[A-Z]+$/.test(columnTitle)) return 'columnTitle uses only uppercase letters.';
  if (columnTitle.length === 7 && columnTitle > 'FXSHRXW') return 'columnTitle is at most "FXSHRXW".';
  return null;
}

