function titleToNumber(columnTitle) {
  const base = 26;
  let result = 0;
  for (let i = 0; i < columnTitle.length; i++) {
    const digit = columnTitle.charCodeAt(i) - 'A'.charCodeAt(0) + 1;
    result = result * base + digit;
  }
  return result;
}

