function titleToNumber(columnTitle) {
  // Count every shorter label, then the label's rank among labels of its own length.
  const length = columnTitle.length;
  let shorter = 0;
  for (let k = 1; k < length; k++) shorter += Math.pow(26, k);
  let rank = 0;
  for (let i = 0; i < length; i++) rank += (columnTitle.charCodeAt(i) - 65) * Math.pow(26, length - 1 - i);
  return shorter + rank + 1;
}

