function generate(rand, size) {
  const pick = k => Math.floor(rand() * k);
  let number;
  if (size === 'large') number = 1 + pick(2147483647);
  else {
    const r = rand();
    number = r < 0.15 ? [1, 26, 27, 52, 53, 702, 703][pick(7)] : r < 0.6 ? 1 + pick(30) : 1 + pick(20000);
  }
  let title = '';
  while (number > 0) {
    const digit = (number - 1) % 26;
    title = String.fromCharCode(65 + digit) + title;
    number = Math.floor((number - 1) / 26);
  }
  return [title];
}
